import {
  AlertTriangle,
  CheckCircle2,
  Database,
  Play,
  RefreshCw,
  ShieldCheck,
  Timer,
  Wrench,
} from 'lucide-react';
import type { CoverageCollector, CoverageResponse, CoverageWindow, OperationsTrends } from '../types';
import { fmtInt, fmtNum1, fmtPct, signed } from '../lib/format';
import { buildRollingPath } from './coveragePaths';
import { EmptyState } from './PanelStates';
import SourceNote from './SourceNote';
import DataVintageBadge from './DataVintageBadge';
import NewHereHint from './NewHereHint';
import type { Vintages } from '../lib/useDataVintages';

/**
 * P3 split: the pure render half of CoveragePanel (no data fetching, no
 * hooks beyond none — everything arrives as props). The data shell lives in
 * `CoveragePanel.tsx` (usePanelData wiring, skeleton/error gating). This
 * file is what the P1 factory tests exercise through the shell; keeping it
 * prop-only means it can be tested without mocking the API at all.
 *
 * Verbatim move from CoveragePanel.tsx — no JSX was edited, only relocated.
 */

const STATUS_LABELS: Record<string, string> = {
  completed: 'Completed',
  partial: 'Partial',
  missed: 'Missed',
  interrupted: 'Interrupted',
  collecting: 'Collecting now',
};

const STATUS_TONE: Record<string, 'green' | 'amber' | 'red' | 'blue'> = {
  completed: 'green',
  partial: 'amber',
  missed: 'red',
  interrupted: 'red',
  collecting: 'blue',
};

export function StatusBadge({ status }: { status: string }) {
  const tone = STATUS_TONE[status] ?? 'amber';
  const cls =
    tone === 'green'
      ? 'bg-optimized/10 text-optimized'
      : tone === 'amber'
        ? 'bg-bottleneck/10 text-bottleneck'
        : tone === 'red'
          ? 'bg-danger/10 text-danger'
          : 'bg-accent/10 text-accent';
  return (
    <span
      className={`inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-semibold ${cls}`}
    >
      {status === 'collecting' && (
        <span className="live-dot h-1.5 w-1.5 rounded-full bg-accent" />
      )}
      {STATUS_LABELS[status] ?? status}
    </span>
  );
}

export function CollectorBadge({ collector }: { collector: CoverageCollector }) {
  if (collector.status === 'running') {
    const cloud = collector.collector_origin === 'cloud';
    return (
      <span className="inline-flex items-center gap-1.5 rounded-full bg-optimized/10 px-2.5 py-1 text-[11px] font-semibold text-optimized">
        <span className="live-dot h-1.5 w-1.5 rounded-full bg-optimized" />
        {cloud ? 'Collector running (cloud)' : 'Collector running'}
      </span>
    );
  }
  if (collector.status === 'stale') {
    return (
      <span className="inline-flex items-center gap-1.5 rounded-full bg-bottleneck/10 px-2.5 py-1 text-[11px] font-semibold text-bottleneck">
        <span className="h-1.5 w-1.5 rounded-full bg-bottleneck" />
        Collector stale — heartbeat quiet
      </span>
    );
  }
  return (
    <span className="inline-flex items-center gap-1.5 rounded-full bg-card-hover px-2.5 py-1 text-[11px] font-semibold text-text-muted">
      <span className="h-1.5 w-1.5 rounded-full bg-text-muted" />
      Collector stopped
    </span>
  );
}

function StatCard({
  label,
  value,
  sub,
  tone,
}: {
  label: string;
  value: string;
  sub?: string;
  tone?: 'green' | 'amber' | 'neutral';
}) {
  const valueClass =
    tone === 'green'
      ? 'text-optimized'
      : tone === 'amber'
        ? 'text-bottleneck'
        : 'text-text-primary';
  return (
    <div className="rounded-xl border border-border bg-card p-3.5">
      <div className="text-[10px] font-semibold text-text-muted">
        {label}
      </div>
      <div className={`mt-1.5 text-2xl font-extrabold tabular-nums leading-none ${valueClass}`}>
        {value}
      </div>
      {sub && <div className="mt-1 text-[10px] leading-snug text-text-muted">{sub}</div>}
    </div>
  );
}

export interface CoverageViewProps {
  data: CoverageResponse;
  trends: OperationsTrends | null;
  vintages: Vintages;
  onReload: () => void;
}

export default function CoverageView({ data, trends, vintages, onReload }: CoverageViewProps) {
  const { collector, summary, issues, recent } = data;
  const lastAudit = data.last_audit;
  const isDemo = data.demo === true;
  const rollup = trends?.available ? trends : null;
  const rollingPoints = rollup?.rolling ?? [];
  const anomalies = rollup?.anomalies ?? [];
  const anomalyByDate = new Map(anomalies.map((a) => [a.date, a]));

  // Trailing-7-weekday rolling trend as two SVG polylines (early %, ghost %).
  // X = index across the collected days, Y = value; each series scales to its
  // own min/max band so small-but-real drift stays visible.
  const rollingPaths: { early?: string; ghost?: string } = {};
  if (rollingPoints.length > 1) {
    const w = 600;
    const h = 56;
    rollingPaths.early = buildRollingPath(rollingPoints, 'pct_early_gt2', w, h);
    rollingPaths.ghost = buildRollingPath(rollingPoints, 'ghost_rate_pct', w, h);
  }

  return (
    <div className="flex flex-col">
      {/* header */}
      <div className="relative overflow-hidden rounded-xl border border-border bg-card px-5 py-5">
        <div className="absolute inset-x-0 top-0 h-1 bg-border" />
        <div className="flex flex-wrap items-center gap-2.5">
          <span className="rounded-xl bg-optimized/15 p-2">
            <Database className="h-5 w-5 text-optimized" />
          </span>
          <h2 className="text-base font-bold text-text-primary">Collection coverage</h2>
          <CollectorBadge collector={collector} />
          {isDemo && (
            <span
              className="inline-flex items-center gap-1 rounded-full bg-accent/10 px-2.5 py-1 text-[10px] font-semibold text-accent"
              title="This ledger was seeded by scripts/seed_demo_data.py so the tabs have content to show. The numbers are synthetic — run the collector (or restore your backup) for real measurements."
            >
              Demo data
            </span>
          )}
          <button
            onClick={onReload}
            className="ml-auto inline-flex items-center gap-1.5 rounded-lg border border-border px-2 py-1 text-[11px] font-semibold text-text-secondary transition-colors hover:bg-card-hover"
            title="Refresh"
          >
            <RefreshCw className="h-3.5 w-3.5" /> Refresh
          </button>
        </div>
        <p className="mt-2 text-xs leading-relaxed text-text-muted">
          What the always-on collector actually captured — and whether it is alive right now.
          Every measured number on this dashboard is only as good as the polling behind it.
        </p>
      </div>

      <div className="mt-3">
        <NewHereHint text="This page is the trust view: it audits the measurement itself. A window marked missed or interrupted means the collector wasn't out there for part of a peak — a gap to know about before quoting the numbers." />
      </div>

      {/* actionable recommendations */}
      {data.available && (
        <div className="mt-4 flex flex-col gap-2">
          {collector.status === 'stale' && (
            <div className="flex items-start gap-2.5 rounded-xl border border-bottleneck/40 bg-bottleneck/10 px-4 py-3">
              <Wrench className="mt-0.5 h-4 w-4 shrink-0 text-bottleneck" />
              <div>
                <span className="text-xs font-bold text-bottleneck">Collector is stale</span>
                <p className="mt-0.5 text-[11px] leading-snug text-text-muted">
                  The heartbeat has gone quiet. Restart it so the next collection window is captured.
                </p>
                <code className="mt-1.5 inline-block rounded bg-card-hover px-2 py-1 text-[10px] text-text-secondary">python scripts/collect_service.py</code>
              </div>
            </div>
          )}
          {collector.status === 'stopped' && (
            <div className="flex items-start gap-2.5 rounded-xl border border-danger/40 bg-danger/10 px-4 py-3">
              <Play className="mt-0.5 h-4 w-4 shrink-0 text-danger" />
              <div>
                <span className="text-xs font-bold text-danger">Collector is not running</span>
                <p className="mt-0.5 text-[11px] leading-snug text-text-muted">
                  No data is being collected, and the cloud collector's last heartbeat is older than the staleness budget. Collection is the VPS's job — check it before starting a local duplicate (a second poller in the synced data home corrupts the ledger).
                </p>
                <code className="mt-1.5 inline-block rounded bg-card-hover px-2 py-1 text-[10px] text-text-secondary">ssh ubuntu@&lt;vps&gt;: systemctl status miway-collector</code>
              </div>
            </div>
          )}
          {(summary.poll_success_rate_pct ?? 100) < 80 && summary.windows > 0 && (
            <div className="flex items-start gap-2.5 rounded-xl border border-amber-500/30 bg-amber-500/10 px-4 py-3">
              <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0 text-amber-400" />
              <div>
                <span className="text-xs font-bold text-amber-400">Low poll success rate ({fmtPct(summary.poll_success_rate_pct)})</span>
                <p className="mt-0.5 text-[11px] leading-snug text-text-muted">
                  Many polls returned empty. Check the collector's network connectivity or the GTFS-RT feed URL.
                </p>
              </div>
            </div>
          )}
          {(summary.by_status.missed ?? 0) > 2 && (
            <div className="flex items-start gap-2.5 rounded-xl border border-amber-500/30 bg-amber-500/10 px-4 py-3">
              <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0 text-amber-400" />
              <div>
                <span className="text-xs font-bold text-amber-400">{summary.by_status.missed} missed windows</span>
                <p className="mt-0.5 text-[11px] leading-snug text-text-muted">
                  These peaks had no collector coverage. Data from adjacent windows may still be usable, but these periods have gaps.
                </p>
              </div>
            </div>
          )}
          {lastAudit && (lastAudit.rows_repaired > 0 || lastAudit.underreported_found > 0) && (
            <div
              className={`flex items-start gap-2.5 rounded-xl border px-4 py-3 ${ lastAudit.rows_repaired > 0 ? 'border-amber-500/30 bg-amber-500/10' : 'border-bottleneck/40 bg-bottleneck/10' }`}
              title="audit_coverage_ledger.py compares the CSV ledger against the per-window JSONs (the authoritative record) and rewrites any row the JSON out-votes. Repairs here mean the ledger had drifted — usually a collector race — and has been corrected."
            >
              <Wrench className="mt-0.5 h-4 w-4 shrink-0 text-amber-400" />
              <div>
                <span className="text-xs font-bold text-amber-400">
                  Ledger self-repaired{lastAudit.checked_at ? ` at ${lastAudit.checked_at}` : ''}
                </span>
                <p className="mt-0.5 text-[11px] leading-snug text-text-muted">
                  {lastAudit.rows_repaired > 0
                    ? `${lastAudit.rows_repaired} ledger row${lastAudit.rows_repaired === 1 ? '' : 's'} underreported by a collector race ${lastAudit.rows_repaired === 1 ? 'was' : 'were'} rewritten from the window JSON truth. Coverage numbers now reflect what was actually captured.`
                    : `${lastAudit.underreported_found} underreported ledger rows detected but not yet repaired (audit ran without --repair).`}
                </p>
              </div>
            </div>
          )}
          {lastAudit && lastAudit.rows_repaired === 0 && lastAudit.underreported_found === 0 && (
            <p className="text-[11px] text-text-muted" title="audit_coverage_ledger.py compares the CSV ledger against the per-window JSONs and found no drift.">
              Ledger audited{lastAudit.checked_at ? ` at ${lastAudit.checked_at}` : ''} · no drift found — a repair notice would appear here if the audit ever rewrites rows.
            </p>
          )}
          {collector.status === 'running' && (summary.poll_success_rate_pct ?? 0) >= 95 && (summary.by_status.missed ?? 0) === 0 && (
            <div className="flex items-start gap-2.5 rounded-xl border border-optimized/30 bg-optimized/10 px-4 py-3">
              <CheckCircle2 className="mt-0.5 h-4 w-4 shrink-0 text-optimized" />
              <div>
                <span className="text-xs font-bold text-optimized">Data looks healthy</span>
                <p className="mt-0.5 text-[11px] leading-snug text-text-muted">
                  Collector is running, poll success is high, and no windows have been missed. The measured numbers on other tabs can be trusted.
                </p>
              </div>
            </div>
          )}
        </div>
      )}

      <div className="mt-4 flex flex-col gap-4">
        {/* status summary */}
        <section className="overflow-hidden rounded-xl border border-border bg-card">
          <div className="flex items-center gap-2.5 px-5 pt-5 pb-3">
            <span className="rounded-lg bg-optimized/15 p-1.5">
              <ShieldCheck className="h-4 w-4 text-optimized" />
            </span>
            <h3 className="text-sm font-bold text-text-primary">Ledger summary</h3>
          </div>
          {data.available ? (
            <>
              <div className="grid grid-cols-2 gap-2.5 px-5 pb-2 sm:grid-cols-3 xl:grid-cols-6">
                <StatCard label="Windows" value={fmtInt(summary.windows)} />
                <StatCard label="Days covered" value={fmtInt(summary.days)} />
                <StatCard
                  label="Collected"
                  value={fmtPct(summary.ok_share_pct)}
                  sub="windows that got their data"
                  tone={(summary.ok_share_pct ?? 100) < 70 ? 'amber' : 'green'}
                />
                <StatCard
                  label="Flawless"
                  value={fmtPct(summary.completed_share_pct)}
                  sub="windows with zero failed polls"
                />
                <StatCard
                  label="Poll success"
                  value={fmtPct(summary.poll_success_rate_pct)}
                  sub="polls that returned data"
                />
                <StatCard
                  label="Longest gap"
                  value={fmtNum1(summary.longest_gap_min)}
                  sub="minutes, worst window"
                  tone={(summary.longest_gap_min ?? 0) > 20 ? 'amber' : 'neutral'}
                />
              </div>
              <div className="grid grid-cols-2 gap-2.5 px-5 pb-5 sm:grid-cols-3 xl:grid-cols-6">
                <StatCard
                  label="Observations"
                  value={fmtInt(summary.observations)}
                  sub="GTFS-RT snapshots"
                />
                <StatCard
                  label="VP snapshots"
                  value={fmtInt(summary.vp_snapshots)}
                  sub="vehicle-position polls"
                />
                <StatCard
                  label="Missed"
                  value={fmtInt(summary.by_status.missed ?? 0)}
                  sub="silent gaps"
                  tone={(summary.by_status.missed ?? 0) > 0 ? 'amber' : 'green'}
                />
                <StatCard
                  label="Interrupted"
                  value={fmtInt(summary.by_status.interrupted ?? 0)}
                  sub="cut short"
                  tone={(summary.by_status.interrupted ?? 0) > 0 ? 'amber' : 'neutral'}
                />
                <StatCard
                  label="Partial"
                  value={fmtInt(summary.by_status.partial ?? 0)}
                  sub="some polls failed"
                />
                <StatCard
                  label="Collecting now"
                  value={fmtInt(summary.by_status.collecting ?? 0)}
                  sub="live windows"
                  tone="neutral"
                />
              </div>

        {/* coverage holes */}
        <section className="overflow-hidden rounded-xl border border-border bg-card">
          <div className="flex items-center gap-2.5 px-5 pt-5 pb-3">
            <span className="rounded-lg bg-danger/15 p-1.5">
              <AlertTriangle className="h-4 w-4 text-danger" />
            </span>
            <h3 className="text-sm font-bold text-text-primary">Coverage holes</h3>
          </div>
          {!data.available ? (
            <div className="px-5 pb-5 text-xs text-text-muted">
              No data yet — nothing to audit.
            </div>
          ) : issues.length === 0 ? (
            <div className="flex items-center gap-2 px-5 pb-5 text-xs text-optimized">
              <CheckCircle2 className="h-4 w-4" />
              No missed or interrupted windows in the record.
            </div>
          ) : (
            <ul className="px-5 pb-5">
              {issues.slice(0, 15).map((issue, index) => (
                <li
                  key={`${issue.date ?? ''}|${issue.window_start ?? ''}|${issue.status}|${index}`}
                  className="flex items-start gap-2.5 border-b border-border/50 py-2 text-xs last:border-0"
                >
                  <StatusBadge status={issue.status} />
                  <div className="min-w-0">
                    <div className="font-semibold text-text-primary">
                      {issue.date ?? '—'} · {issue.scheduled ?? 'unknown window'}
                    </div>
                    <div className="text-[11px] leading-snug text-text-muted">{issue.note}</div>
                  </div>
                </li>
              ))}
              {issues.length > 15 && (
                <li className="pt-2.5 text-[11px] text-text-muted">
                  …and {issues.length - 15} more affected windows in the full record.
                </li>
              )}
            </ul>
          )}
        </section>

              <div className="flex items-center justify-between gap-3 border-t border-border bg-bg/40 px-5 py-2.5">
                <span className="text-[10px] text-text-muted">
                  {summary.first_date ?? '—'} → {summary.last_date ?? '—'} ·{' '}
                  {collector.last_poll_at ? `last poll ${collector.last_poll_at}` : 'no polls yet'}
                </span>
                <SourceNote source={data.source} />
              </div>
            </>
          ) : (
            <div className="px-5 pb-5">
              <EmptyState
                title="No coverage records yet"
                hint="The collector writes a record for every window it enters. Nothing here means it has never run — start it and this fills in window by window."
                command="python scripts/collect_service.py"
              />
            </div>
          )}
        </section>

        {/* day-over-day drift (the old measured-trends monitor, folded here) */}
        <section className="overflow-hidden rounded-xl border border-border bg-card">
          <div className="flex items-center gap-2.5 px-5 pt-5 pb-3">
            <span className="rounded-lg bg-optimized/15 p-1.5">
              <ShieldCheck className="h-4 w-4 text-optimized" />
            </span>
            <h3 className="text-sm font-bold text-text-primary">Measured drift, day to day</h3>
            {rollup?.schedule_block_boundary && (
              <span
                title={`The timetable currently in effect began ${rollup.schedule_block_boundary} (derived from the GTFS feed). All week-over-week and rolling comparisons stay within this schedule era.`}
                className="ml-auto rounded bg-text-muted/10 px-1.5 py-0.5 text-[9px] font-semibold text-text-muted"
              >
                {rollup.schedule_block_boundary <= new Date().toISOString().slice(0, 10).replace(/-/g, '')
                  ? 'schedule era since '
                  : 'new era starts '}
                {rollup.schedule_block_boundary.slice(4, 6)}/
                {rollup.schedule_block_boundary.slice(6, 8)}/
                {rollup.schedule_block_boundary.slice(0, 4)}
              </span>
            )}
          </div>
          {rollup && rollup.rows.length > 0 ? (
            <>
              {rollup.week_over_week ? (
                <div className="mx-5 mb-3 flex flex-wrap items-center gap-x-5 gap-y-1 rounded-xl border border-border bg-card-hover px-4 py-2.5 text-[11px]">
                  <span className="font-bold text-text-muted">
                    Week over week
                  </span>
                  {rollup.week_over_week.spans_schedule_change && (
                    <span
                      title="The new timetable started on Sept 8, so the previous week ran a different schedule. This delta is the schedule change, not a service improvement or regression."
                      className="rounded bg-accent/15 px-1.5 py-px text-[9px] font-semibold text-accent"
                    >
                      schedule changed Sept 8
                    </span>
                  )}
                  <span className="text-text-muted">
                    Departures{' '}
                    <b
                      className={`tabular-nums ${ (rollup.week_over_week.recorded_change_pct ?? 0) < -20 ? 'text-bottleneck' : 'text-text-primary' }`}
                    >
                      {signed(rollup.week_over_week.recorded_change_pct)}%
                    </b>
                  </span>
                  <span className="text-text-muted">
                    Ghost rate{' '}
                    <b
                      className={`tabular-nums ${ (rollup.week_over_week.ghost_rate_change_pct ?? 0) > 50 ? 'text-bottleneck' : 'text-text-primary' }`}
                    >
                      {signed(rollup.week_over_week.ghost_rate_change_pct)}%
                    </b>
                  </span>
                  <span className="text-text-muted">
                    Early departures{' '}
                    <b className="tabular-nums text-text-primary">
                      {signed(rollup.week_over_week.pct_early_change_pp)}pp
                    </b>
                  </span>
                  <span className="text-text-muted">
                    ({rollup.week_over_week.this_week.days} vs{' '}
                    {rollup.week_over_week.previous_week.days} weekdays
                    {rollup.week_over_week.n_holiday_days_skipped > 0
                      ? ` · ${rollup.week_over_week.n_holiday_days_skipped} holiday${rollup.week_over_week.n_holiday_days_skipped > 1 ? 's' : ''} skipped`
                      : ''}
                    )
                  </span>
                </div>
              ) : rollup.wow_unavailable_reason ? (
                <div
                  className="mx-5 mb-3 rounded-xl border border-border bg-card-hover px-4 py-2.5 text-[11px] text-text-muted"
                  title="Week-over-week compares like-for-like weekdays within the same timetable. Nothing is hidden — the comparison becomes possible once a second week of the current schedule exists."
                >
                  <span className="font-bold text-text-muted">
                    Week over week{' '}
                  </span>
                  {rollup.wow_unavailable_reason}
                </div>
              ) : null}
              <p className="px-5 pb-3 text-[11px] leading-relaxed text-text-muted">
                How the collector's daily rollup drifts: ghost trips and early
                departures per collected day, so a jump (or a quiet data drop) is
                visible next to the coverage ledger instead of buried in a snapshot.
              </p>
              <div className="overflow-x-auto px-5 pb-4">
                <div className="flex min-w-max gap-2.5 pb-1">
                  {[...rollup.rows].reverse().map((row, index) => {
                    const earlyHot = (row.pct_early_gt2 ?? 0) > 25;
                    const ghostHot = (row.ghost_trips ?? 0) > 0;
                    const drop = row.observations === 0;
                    const anomaly = anomalyByDate.get(row.date);
                    return (
                      <div
                        key={`${row.date}-${index}`}
                        className={`relative w-40 rounded-xl border p-3 ${ drop ? 'border-danger/40 bg-danger/10' : anomaly ? 'border-rose-500/60 bg-rose-500/10 ring-1 ring-rose-500/30' : row.is_holiday ? 'border-violet-500/40 bg-violet-500/10' : ghostHot || earlyHot ? 'border-amber-500/40 bg-amber-500/10' : 'border-border bg-card-hover' }`}
                      >
                        <div className="flex items-center justify-between text-[10px] font-semibold text-text-muted">
                          <span>{row.date.slice(5)}</span>
                          {row.is_holiday && (
                            <span
                              className="rounded bg-violet-500/20 px-1 py-0.5 text-[9px] text-violet-600 dark:text-violet-300"
                              title="Statutory holiday — holiday schedule ran, so this day is not comparable to a normal weekday"
                            >
                              Holiday
                            </span>
                          )}
                        </div>
                        <div className="mt-2 space-y-1.5 text-[11px]">
                          <div className="flex items-center justify-between">
                            <span className="text-text-muted">Ghosts</span>
                            <span
                              className={`font-bold tabular-nums ${ghostHot ? 'text-bottleneck' : 'text-text-primary'}`}
                            >
                              {fmtInt(row.ghost_trips)} ({fmtPct(row.ghost_rate_pct)})
                            </span>
                          </div>
                          <div className="flex items-center justify-between">
                            <span className="text-text-muted">Early</span>
                            <span
                              className={`font-bold tabular-nums ${earlyHot ? 'text-bottleneck' : 'text-text-primary'}`}
                            >
                              {fmtPct(row.pct_early_gt2)}
                            </span>
                          </div>
                          <div className="flex items-center justify-between">
                            <span
                              className="text-text-muted"
                              title="Recorded departures that day (raw poll snapshots are ~100× this; they count every 30-second vehicle snapshot, not records)">
                              Rec
                            </span>
                            <span className={`font-bold tabular-nums ${drop ? 'text-danger' : 'text-text-primary'}`}>
                              {fmtInt(row.n_recorded)}
                            </span>
                          </div>
                          {anomaly && (
                            <div
                              className="mt-2 rounded-lg bg-rose-500/15 px-2 py-1 text-[10px] font-semibold text-rose-600 dark:text-rose-300"
                              title={
                                Object.entries(anomaly.metrics)
                                  .map(
                                    ([k, m]) =>
                                      `${k === 'ghost_rate_pct' ? 'ghost rate' : 'early share'} ${m!.value}% vs ${m!.baseline_mean}% baseline (${m!.z}σ ${m!.direction})`,
                                  )
                                  .join('; ') +
                                (anomaly.is_holiday ? ' — holiday service' : '')
                              }
                            >
                              ⚠ {Object.keys(anomaly.metrics).length > 1 ? '3σ outlier' : anomaly.metrics.ghost_rate_pct ? 'ghost rate 3σ outlier' : 'early share 3σ outlier'}
                              {anomaly.is_holiday ? ' (holiday)' : anomaly.is_weekend ? ' (weekend)' : ''}
                            </div>
                          )}
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
              {rollingPoints.length > 1 && (
                <div className="px-5 pb-4">
                  <div className="mb-1.5 flex items-baseline justify-between">
                    <span className="text-[10px] font-semibold text-text-muted">
                      7-weekday rolling trend (holidays skipped)
                    </span>
                    <span className="text-[10px] text-text-muted">
                      {rollingPoints[rollingPoints.length - 1].date.slice(5)}
                    </span>
                  </div>
                  <svg viewBox="0 0 600 56" className="h-14 w-full" preserveAspectRatio="none">
                    {rollingPaths.early && (
                      <path
                        d={rollingPaths.early}
                        fill="none"
                        stroke="currentColor"
                        className="text-bottleneck"
                        strokeWidth="1.8"
                      />
                    )}
                    {rollingPaths.ghost && (
                      <path
                        d={rollingPaths.ghost}
                        fill="none"
                        stroke="currentColor"
                        className="text-optimized"
                        strokeWidth="1.8"
                      />
                    )}
                  </svg>
                  <div className="flex justify-between text-[10px] text-text-muted">
                    <span>
                      <span className="text-bottleneck">—</span> early departures %
                    </span>
                    <span>
                      <span className="text-optimized">—</span> ghost rate %
                    </span>
                  </div>
                </div>
              )}
              <div className="flex flex-wrap items-center justify-between gap-x-4 gap-y-1 border-t border-border bg-bg/40 px-5 py-2.5">
                <span className="min-w-0 flex-1 basis-64 text-[10px] text-text-muted">
                  Red = quiet data drop (0 observations). Amber = ghost trips or &gt;25% early
                  departures that day. Violet = statutory holiday (holiday schedule, not comparable
                  to a weekday). Ghost % = ghosts ÷ verifiable scheduled trips.
                </span>
                <SourceNote source={rollup.file ?? 'weekly_rollup.csv'} />
                <DataVintageBadge vintage={vintages.weekly_rollup} />
              </div>
            </>
          ) : (
            <div className="px-5 pb-5">
              <EmptyState
                title="No rollup history yet"
                hint="The weekly rollup is generated from collected days. Empty until at least one day's collection has been rolled up."
              />
            </div>
          )}
        </section>

        {/* recent windows */}
        <section className="overflow-hidden rounded-xl border border-border bg-card">
          <div className="flex items-center gap-2.5 px-5 pt-5 pb-3">
            <span className="rounded-lg bg-accent/15 p-1.5">
              <Timer className="h-4 w-4 text-accent" />
            </span>
            <h3 className="text-sm font-bold text-text-primary">Recent windows</h3>
          </div>
          {data.available && recent.length > 0 ? (
            <>
              {/* T165 M5: local x-scroll — bare px-5 pb-4 let the 418px table
                  ride the outer page scroll on phones. */}
              <div className="overflow-x-auto px-5 pb-4">
                <table className="data-table w-full text-left text-xs">
                  <thead>
                    <tr className="border-b border-border text-[10px] text-text-muted">
                      <th className="py-1.5 pr-3 font-semibold">Date</th>
                      <th className="py-1.5 pr-3 font-semibold">Window</th>
                      <th className="py-1.5 pr-3 font-semibold">Status</th>
                      <th className="py-1.5 pr-3 font-semibold">Polls</th>
                      <th className="py-1.5 pr-3 font-semibold">Obs</th>
                      <th className="py-1.5 pr-3 font-semibold">VP</th>
                      <th className="py-1.5 text-right font-semibold">Longest gap</th>
                    </tr>
                  </thead>
                  <tbody>
                    {recent.map((w: CoverageWindow) => (
                      <tr
                        key={w.window_start ?? w.date ?? 'row'}
                        className="border-b border-border/50 text-text-secondary"
                      >
                        <td className="py-2 pr-3 tabular-nums text-text-primary">
                          {w.date ?? '—'}
                        </td>
                        <td className="py-2 pr-3 tabular-nums">{w.scheduled ?? '—'}</td>
                        <td className="py-2 pr-3">
                          <StatusBadge status={w.status} />
                        </td>
                        <td className="py-2 pr-3 tabular-nums">
                          {w.polls_attempted > 0
                            ? `${w.polls_succeeded}/${w.polls_attempted}`
                            : '—'}
                        </td>
                        <td className="py-2 pr-3 tabular-nums">{fmtInt(w.observations)}</td>
                        <td className="py-2 pr-3 tabular-nums">{fmtInt(w.vp_snapshots)}</td>
                        <td className="py-2 text-right tabular-nums">
                          {w.longest_gap_min > 0 ? fmtNum1(w.longest_gap_min) : '—'}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              <div className="flex items-center justify-between gap-3 border-t border-border bg-bg/40 px-5 py-2.5">
                <span className="text-[10px] text-text-muted">
                  completed = every poll succeeded · partial = some polls failed ·
                  missed = no poll succeeded · interrupted = cut short · collecting = live now
                </span>
                <SourceNote source={data.source} />
              </div>
            </>
          ) : (
            <div className="px-5 pb-5">
              <EmptyState
                title="No windows recorded"
                hint="Start the collector and a record appears here for every window it enters."
                command="python scripts/collect_service.py"
              />
            </div>
          )}
        </section>
      </div>
    </div>
  );
}
