import { api } from '../lib/api';
import { usePanelData } from '../hooks/usePanelData';
import type { CoverageResponse, OperationsTrends } from '../types';
import { PanelSkeleton } from './PanelStates';
import CoverageView from './CoverageView';
import { useDataVintages } from '../lib/useDataVintages';

/**
 * Collection coverage (trust view): the ledger of what the always-on
 * collector actually captured, and whether it is alive right now.
 *
 * Every measured number on this dashboard is only as good as the polling
 * that produced it, so this panel answers: was the collector out there, when,
 * and did the window finish — or is there a silent gap we're about to quote
 * numbers over?
 *
 * P3 split: this file is the DATA SHELL only — usePanelData wiring plus the
 * skeleton/error gates. All rendering (header, recommendations, ledger
 * summary, drift cards, recent windows) lives in `CoverageView.tsx` as a
 * prop-only component, so the view can be tested without mocking the API.
 */
export default function CoveragePanel() {
  const vintages = useDataVintages();

  // P2: two hook instances, one per endpoint. The old code merged them into
  // one load() with Promise.allSettled so a trends failure couldn't blank the
  // panel — two independent instances give the same isolation for free (each
  // has its own error state; only the coverage one renders the panel-level
  // error). The P0.8 abort/poll discipline is owned by the hook: same
  // newest-poll-wins semantics, same 60 s cadence; polling.test.tsx's
  // contract pins carry over (they assert api.coverage call counts, which
  // this wiring preserves exactly).
  const { data, error, loading, reload } = usePanelData<CoverageResponse>({
    fetcher: (signal) => api.coverage({ signal }),
    pollMs: 60_000,
  });
  const { data: trends } = usePanelData<OperationsTrends>({
    fetcher: (signal) => api.operationsTrends({ signal }),
    pollMs: 60_000,
  });

  if (loading && !data) {
    return <PanelSkeleton label="Loading collection coverage…" />;
  }

  if (error && !data) {
    return (
      <div
        role="alert"
        className="rounded-xl border border-danger/40 bg-danger/10 p-6 text-sm text-danger"
      >
        Could not load collection coverage: {error}
      </div>
    );
  }
  if (!data) return null;

  return (
    <CoverageView data={data} trends={trends} vintages={vintages} onReload={reload} />
  );
}
